mapper.select:
SELECT ROW_NO, COLUMN_NO, VALUE_TYPE, TEXT_VALUE, NUMBER_VALUE,
       DATETIME_VALUE, BOOLEAN_YN, FORMULA_VALUE, STYLE_SEQ
  FROM wo_sheet_cell_line
 WHERE SHEET_SEQ  = #{sheetSeq}
   AND ROW_NO    BETWEEN #{range.fromRowNo}    AND #{range.toRowNo}
   AND COLUMN_NO BETWEEN #{range.fromColumnNo} AND #{range.toColumnNo}
   AND DEL_DATETIME IS NULL
 ORDER BY ROW_NO, COLUMN_NO

mapper.update:
UPDATE wo_sheet_cell_line
   SET DEL_DATETIME = CURRENT_TIMESTAMP,
       DEL_USER      = #{userKey}
 WHERE SHEET_SEQ = #{sheetSeq}
   AND DEL_DATETIME IS NULL
   AND (

       (ROW_NO = #{cell.rowNo} AND COLUMN_NO = #{cell.columnNo})

       )

mapper.insert:
INSERT INTO wo_sheet_cell_line (
    SHEET_SEQ, ROW_NO, COLUMN_NO, VALUE_TYPE, TEXT_VALUE, NUMBER_VALUE,
    DATETIME_VALUE, BOOLEAN_YN, FORMULA_VALUE, STYLE_SEQ,
    INPUT_DATETIME, INPUT_USER
) VALUES (
    #{sheetSeq}, #{cell.rowNo}, #{cell.columnNo}, #{cell.valueType},
    #{cell.textValue}, #{cell.numberValue}, #{cell.datetimeValue},
    #{cell.booleanYn}, #{cell.formulaValue}, #{cell.styleSeq},
    CURRENT_TIMESTAMP, #{userKey}
)
